import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import './Auth.css';

function EmployeeLogin() {
  const [formData, setFormData] = useState({
    employeeId: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    console.log('Attempting employee login...');

    try {
      const response = await api.post('/employee/login', formData);

      console.log('Login successful:', response.data);

      localStorage.setItem('employeeToken', response.data.token);
      localStorage.setItem('employee', JSON.stringify(response.data.employee));

      navigate('/employee/dashboard');
    } catch (err) {
      console.error('Login error:', err);
      const errorMessage = err.response?.data?.error || 'Login failed. Please try again.';
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <h2>Employee Login</h2>
        <p style={{textAlign: 'center', color: '#666', marginBottom: '20px'}}>
          Staff Portal - Transaction Verification
        </p>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Employee ID</label>
            <input
              type="text"
              name="employeeId"
              value={formData.employeeId}
              onChange={handleChange}
              required
              placeholder="e.g., EMP001"
            />
          </div>

          <div className="form-group">
            <label>Password</label>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
              placeholder="Enter your password"
            />
          </div>

          {error && <div className="error-message">{error}</div>}

          <button type="submit" disabled={loading} className="btn-primary">
            {loading ? 'Logging in...' : 'Login'}
          </button>
        </form>

        <p className="auth-link">
          <a href="/login">Customer Login</a>
        </p>

        <div style={{
          marginTop: '20px', 
          padding: '16px', 
          background: '#f0f0f0', 
          borderRadius: '8px', 
          fontSize: '13px'
        }}>
          <strong>Test Credentials:</strong><br/>
          Employee ID: <code style={{background: '#e0e0e0', padding: '2px 6px', borderRadius: '4px'}}>EMP001</code><br/>
          Password: <code style={{background: '#e0e0e0', padding: '2px 6px', borderRadius: '4px'}}>Admin123!</code>
        </div>
      </div>
    </div>
  );
}

export default EmployeeLogin;
